PAYLOAD = ''
"""Local node preparation only: pinned provider, native tests, existing inputs.

No SDK initialize, UB allocation, Guest, service or kernel modification.
Run independently on each node. No SSH or cross-node network operations.
"""
import argparse
import base64
import ctypes
import hashlib
import io
import json
import os
from pathlib import Path
import platform
import stat
import subprocess
import sys
import tarfile
import time
import zlib


ROOT = Path('/home/jwk/agent')


def need(condition, message):
    if not condition:
        raise RuntimeError(message)


def digest(path):
    result = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for part in iter(lambda: stream.read(1048576), b''):
            result.update(part)
    return result.hexdigest()


def save(path, value):
    with Path(path).open('x', encoding='utf-8') as stream:
        json.dump(value, stream, indent=2, ensure_ascii=False)
        stream.write('\n')
        stream.flush()
        os.fsync(stream.fileno())


def unpack(work):
    data = zlib.decompress(base64.b64decode(PAYLOAD))
    need(hashlib.sha256(data).hexdigest() == ARCHIVE_SHA256, 'Embedded source archive differs')
    with tarfile.open(fileobj=io.BytesIO(data)) as archive:
        names = set()
        for member in archive.getmembers():
            name = Path(member.name)
            need(member.isfile() and not name.is_absolute() and '..' not in name.parts
                 and member.name not in names and member.name in SOURCE_HASHES, 'Invalid packet member')
            names.add(member.name)
            content = archive.extractfile(member).read()
            need(hashlib.sha256(content).hexdigest() == SOURCE_HASHES[member.name], 'Packet file differs')
            output = work / 'source' / name
            output.parent.mkdir(parents=True, exist_ok=True)
            with output.open('xb') as stream:
                stream.write(content)
        need(names == set(SOURCE_HASHES), 'Incomplete source packet')


def phase(work, report, name, command, timeout, env=None):
    print('PHASE=' + name, flush=True)
    begin = time.monotonic()
    with (work / (name + '.log')).open('xb') as log:
        result = subprocess.run(command, stdout=log, stderr=subprocess.STDOUT,
                                timeout=timeout, env=env, cwd=work)
    report['phases'][name] = {'exitCode': result.returncode,
        'seconds': round(time.monotonic() - begin, 3), 'log': str(work / (name + '.log'))}
    need(result.returncode == 0, 'Native phase failed: ' + name)


def inventory(work, report):
    deployments = ('agentenv-lazy-four-32ce41c', 'agentenv-dsec-hostfile-v1',
                   'agentenv-ae9c626-baseline')
    candidates = []
    for name in deployments:
        path = ROOT / 'deployments' / name / 'rootfs-inputs.json'
        if not path.is_file() or path.is_symlink():
            continue
        need(path.stat().st_size <= 8 * 1024**2, 'Oversized retained input inventory')
        value = json.loads(path.read_text())
        if value.get('status') != 'ORDINARY_FOUR_SNAPSHOTS_SEEDED_NOT_GUEST_ACCEPTANCE':
            continue
        repo = Path(value['repository'])
        need(repo.is_absolute() and repo.resolve(strict=True) == repo and repo.is_relative_to(ROOT),
             'Unexpected retained repository')
        templates = []
        for index, template in enumerate(value['templates']):
            layers = template['rootfsLayers']
            need(isinstance(layers, list) and layers, 'Missing ordinary rootfs layers')
            unique = {}
            for layer in layers:
                key, size = layer['digest'], layer['size']
                need(isinstance(key, str) and key.startswith('sha256:') and len(key) == 71
                     and all(c in '0123456789abcdef' for c in key[7:])
                     and type(size) is int and size > 0, 'Malformed retained layer')
                source = repo / 'managed-layers' / (key.replace(':', '_') + '.overlaybd.commit')
                need(source.resolve(strict=True) == source and source.is_file()
                     and source.stat().st_size == size, 'Missing/changed retained lower')
                need(key not in unique or unique[key]['size'] == size, 'Conflicting retained layer size')
                unique[key] = {'digest': key, 'size': size, 'file': str(source)}
            templates.append({'templateIndex': index, 'layers': list(unique.values()),
                'logicalBytes': sum(r['size'] for r in unique.values()),
                'roundedObjectBytes': sum((r['size'] + 4096 + 4194303) // 4194304 * 4194304
                                          for r in unique.values())})
        candidates.append({'seed': str(path), 'seedSha256': digest(path), 'repository': str(repo),
                           'templates': templates})
    save(work / 'retained-inventory.json', candidates)
    report['retainedInputCandidates'] = [{'seed': x['seed'], 'seedSha256': x['seedSha256'],
        'templates': [{k: v for k, v in t.items() if k != 'layers'} for t in x['templates']]}
        for x in candidates]
    # Hash binaries for version binding; do not hash/read any API key or payload.
    report['binaryCandidates'] = []
    roots = [ROOT / 'builds/dsec-hostfile-release-v2/artifacts']
    roots += [ROOT / 'deployments' / name / part for name in deployments
              for part in ('bin', 'runtime/bin', 'cli/bin')]
    for root in roots:
        for name in ('server', 'firecracker', 'uvm-ublk-daemon', 'aenv', 'aenv-native'):
            path = root / name
            if path.is_file() and not path.is_symlink():
                need(path.resolve(strict=True).is_relative_to(ROOT), 'Binary outside retained workspace')
                report['binaryCandidates'].append({'path': str(path), 'bytes': path.stat().st_size,
                                                    'sha256': digest(path)})


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--node', choices=('a', 'b'), required=True)
    parser.add_argument('--run', action='store_true')
    args = parser.parse_args()
    report = {'status': 'DIRECT_UB_PREPARATION_PLAN', 'node': args.node, 'coreCommit': CORE,
        'SDK_called': False, 'Guest_created': False, 'servicesChanged': False,
        'kernelChanged': False, 'twoNodeAccepted': False, 'netSavingsBytes': None,
        'phases': {}, 'scope': 'native preparation; not Guest or physical sharing acceptance'}
    work = ROOT / 'r' / ('ud-' + args.node + '-v1')
    if not args.run:
        report['workDirectory'] = str(work)
        print(json.dumps(report, indent=2))
        return 0
    created = False
    try:
        need(sys.platform == 'linux' and platform.machine() == 'aarch64', 'Requires native Linux ARM64')
        need(platform.node() == ('server1' if args.node == 'a' else 'agent1'), 'Wrong node')
        need(os.getuid() == os.geteuid() == 1204, 'Run as jwk UID1204, never root')
        caps = [line.split()[1] for line in Path('/proc/self/status').read_text().splitlines()
                if line.startswith(('CapInh:', 'CapPrm:', 'CapEff:', 'CapAmb:'))]
        need(len(caps) == 4 and not any(int(c, 16) for c in caps), 'Ordinary zero-capability process required')
        need(ROOT.resolve(strict=True) == ROOT and work.parent.resolve(strict=True) == work.parent,
             'Missing/redirected workspace')
        need(not work.exists() and not work.is_symlink(), 'Previous preparation preserved; do not rerun')
        os.umask(0o077)
        work.mkdir(mode=0o700)
        created = True
        report['workDirectory'] = str(work)
        report['kernel'] = platform.release()
        report['bootId'] = Path('/proc/sys/kernel/random/boot_id').read_text().strip()
        unpack(work)
        temp = work / 't'
        temp.mkdir()
        env = dict(os.environ, PYTHONPATH=str(work / 'source'), TMPDIR=str(temp), TMP=str(temp), TEMP=str(temp))
        phase(work, report, 'provider-tests', [sys.executable, '-B', '-m', 'unittest',
              'discover', '-s', str(work / 'source/tests'), '-v'], 180, env)
        phase(work, report, 'sdk-adapter-build', ['/usr/bin/g++', '-std=c++17', '-O2', '-shared', '-fPIC',
              '-pthread', '-Wall', '-Wextra', '-Werror', '-I/usr/include', str(work / 'source/sdk_adapter.cpp'),
              '/usr/lib64/libubsm_sdk.so', '-Wl,-rpath,/usr/lib64', '-Wl,-z,relro,-z,now',
              '-o', str(work / 'libaenv-ub.so')], 180)
        library = ctypes.CDLL(str(work / 'libaenv-ub.so'))
        library.aenv_ub_abi_version.argtypes = []
        library.aenv_ub_abi_version.restype = ctypes.c_int
        need(library.aenv_ub_abi_version() == 3, 'Adapter ABI differs')
        report['adapter'] = {'path': str(work / 'libaenv-ub.so'), 'sha256': digest(work / 'libaenv-ub.so'),
                             'bytes': (work / 'libaenv-ub.so').stat().st_size, 'abi': 3}
        print('PHASE=retained-input-and-binary-inventory', flush=True)
        inventory(work, report)
        report['status'] = 'DIRECT_UB_NATIVE_PREPARED_NOT_DEPLOYED'
        report['nextGate'] = 'Bind actual retained inputs/binaries and UB budget before publication or Guest creation'
    except Exception as error:
        report.update(status='STOPPED_DIRECT_UB_PREPARATION_PRESERVE_OUTPUTS',
                      errorType=type(error).__name__, reason=str(error))
    if created:
        save(work / 'preparation-report.json', report)
    print('BEGIN_DIRECT_UB_PREPARATION_REPORT')
    print(json.dumps(report, indent=2))
    print('END_DIRECT_UB_PREPARATION_REPORT')
    return 0 if report['status'] == 'DIRECT_UB_NATIVE_PREPARED_NOT_DEPLOYED' else 1


if __name__ == '__main__':
    raise SystemExit(main())
